<section class="sw-card"><header class="sw-section-heading"><div><h2>Tribunal y defensa</h2><p>Información institucional disponible en modo consulta.</p></div></header><div class="sw-summary-grid"><div><dt>Estado</dt><dd><?= e($statusLabel) ?></dd></div><div><dt>Defensa</dt><dd><?= e(!empty($studentDefense['defense_date']) ? $formatDate((string)$studentDefense['defense_date']) : 'No programada') ?></dd></div><?php if (!empty($studentDefense['defense_time'])): ?><div><dt>Hora</dt><dd><?= e(substr((string)$studentDefense['defense_time'], 0, 5)) ?></dd></div><?php endif; ?><?php if (!empty($studentDefense['location'])): ?><div><dt>Lugar</dt><dd><?= e((string)$studentDefense['location']) ?></dd></div><?php endif; ?></div><div class="sw-record-list"><?php if (!$tribunalMembers): ?><p class="sw-empty-state">El Tribunal todavía no ha sido asignado.</p><?php else: ?><?php foreach ($tribunalMembers as $member): ?><article class="sw-record"><strong><?= e(trim((string)($member['academic_title'] ?? '') . ' ' . (string)($member['full_name'] ?? ''))) ?></strong><small>Miembro de Tribunal</small></article><?php endforeach; ?><?php endif; ?></div></section>
